SELECT * FROM jsonb_to_recordset($group_order$
[{"slug":"ls-fastcup-10","teamName":"Z","sortOrder":1},{"slug":"ls-fastcup-10","teamName":"котята","sortOrder":2},{"slug":"ls-fastcup-10","teamName":"Megan Fox","sortOrder":3},{"slug":"ls-fastcup-10","teamName":"дристал какалс","sortOrder":4},{"slug":"ls-fastcup-11","teamName":"toxic players","sortOrder":1},{"slug":"ls-fastcup-11","teamName":"Iceberg enjoers","sortOrder":2},{"slug":"ls-fastcup-11","teamName":"Синevo","sortOrder":3},{"slug":"ls-fastcup-11","teamName":"Госпожа и каблучки","sortOrder":4},{"slug":"ls-fastcup-11","teamName":"Ztreme Gaming","sortOrder":5},{"slug":"ls-fastcup-11","teamName":"роблокс мафия","sortOrder":6},{"slug":"ls-fastcup-12","teamName":"SashiMi","sortOrder":1},{"slug":"ls-fastcup-12","teamName":"зайчик жуди хопс","sortOrder":2},{"slug":"ls-fastcup-12","teamName":"РОЙ БИДРИЛ","sortOrder":3},{"slug":"ls-fastcup-12","teamName":"Z","sortOrder":4},{"slug":"ls-fastcup-13","teamName":"Z","sortOrder":1},{"slug":"ls-fastcup-13","teamName":"aRAGEbzeb","sortOrder":2},{"slug":"ls-fastcup-13","teamName":"uRETRO Team","sortOrder":3},{"slug":"ls-fastcup-13","teamName":"TTaPaLLIa","sortOrder":4}]
$group_order$::jsonb) AS source(
  slug TEXT, "teamName" TEXT, "sortOrder" SMALLINT
);

INSERT INTO tournament_group_teams (group_id, application_id, sort_order)
SELECT tournament_group.id, application.id, source."sortOrder"
FROM imported_fastcup_group_order source
JOIN tournaments tournament ON tournament.slug = source.slug
JOIN tournament_groups tournament_group
  ON tournament_group.tournament_id = tournament.id
 AND tournament_group.name = 'Общая группа'
JOIN tournament_team_applications application
  ON application.tournament_id = tournament.id
 AND application.team_name = source."teamName"
ON CONFLICT (group_id, application_id) DO NOTHING;

