 3","groupName":"Общая группа","teamA":"Z","teamB":"TTaPaLLIa","bestOf":1,"scheduledAt":"2026-06-13T23:00:00+03:00","bracketRound":3,"bracketSide":"group","bracketSlot":2,"scoreA":1,"scoreB":0,"resultType":"normal","labelA":null,"labelB":null,"decisionNote":null,"sortOrder":6},{"slug":"ls-fastcup-13","matchKey":"sf1","stage":"Плей-офф · Полуфинал","groupName":null,"teamA":"aRAGEbzeb","teamB":"uRETRO Team","bestOf":1,"scheduledAt":"2026-06-14T20:00:00+03:00","bracketSide":"upper","bracketSlot":1,"isFinal":false,"scoreA":1,"scoreB":0,"resultType":"normal","labelA":null,"labelB":null,"decisionNote":null,"bracketRound":1,"winnerToKey":"gf","winnerToSlot":"b","eliminatedTeam":"uRETRO Team","sortOrder":7},{"slug":"ls-fastcup-13","matchKey":"gf","stage":"Гранд-финал","groupName":null,"teamA":"Z","teamB":"aRAGEbzeb","bestOf":3,"scheduledAt":"2026-06-14T21:15:00+03:00","bracketSide":"grand_final","bracketSlot":1,"isFinal":true,"scoreA":2,"scoreB":0,"resultType":"normal","labelA":null,"labelB":null,"decisionNote":null,"bracketRound":2,"eliminatedTeam":"aRAGEbzeb","sortOrder":8}]
$matches$::jsonb) AS source(
  slug TEXT, "matchKey" TEXT, "scheduledAt" TIMESTAMPTZ, stage TEXT,
  "groupName" TEXT, "teamA" TEXT, "teamB" TEXT,
  "scoreA" SMALLINT, "scoreB" SMALLINT, "bestOf" SMALLINT,
  "resultType" TEXT, "labelA" TEXT, "labelB" TEXT, "decisionNote" TEXT,
  "bracketRound" SMALLINT, "bracketSide" TEXT, "bracketSlot" SMALLINT,
  "winnerToKey" TEXT, "winnerToSlot" CHAR(1),
  "loserToKey" TEXT, "loserToSlot" CHAR(1),
  "eliminatedTeam" TEXT, "sortOrder" SMALLINT, "isFinal" BOOLEAN
);

INSERT INTO tournament_matches (
  tournament_id, group_id, scheduled_at, stage,
  team_a_application_id, team_b_application_id,
  team_a_score, team_b_score, best_of, status, sort_order,
  result_type, team_a_result_label, team_b_result_label, decision_note,
  bracket_round, bracket_side, bracket_slot,
  eliminated_team_application_id
)
SELECT
  tournament.id, tournament_group.id, source."scheduledAt", source.stage,
  team_a.id, team_b.id, source."scoreA", source."scoreB", source."bestOf",
  'finished', source."sortOrder", source."resultType", source."labelA",
  source."labelB", source."decisionNote", source."bracketRound",
  source."bracketSide", source."bracketSlot", eliminated_team.id
FROM imported_fastcup_matches source
JOIN tournaments tournament ON tournament.slug = source.slug
JOIN tournament_team_applications team_a
  ON team_a.tournament_id = tournament.id AND team_a.team_name = source."teamA"
JOIN tournament_team_applications team_b
  ON team_b.tournament_id = tournament.id AND team_b.team_name = source."teamB"
LEFT JOIN tournament_groups tournament_group
  ON tournament_group.tournament_id = tournament.id
 AND tournament_group.name = source."groupName"
LEFT JOIN tournament_team_applications eliminated_team
  ON eliminated_team.tournament_id = tournament.id
 AND eliminated_team.team_name = source."eliminatedTeam"
WHERE NOT EXISTS (
  SELECT 1 FROM tournament_matches existing
  WHERE existing.tournament_id = tournament.id
    AND existing.sort_order = source."sortOrder"
);

UPDATE tournament_matches source_match
SET winner_to_match_id = winner_match.id,
    winner_to_slot = source."winnerToSlot",
    loser_to_match_id = loser_match.id,
    loser_to_slot = source."loserToSlot"
FROM imported_fastcup_matches source
JOIN tournaments tournament ON tournament.slug = source.slug
LEFT JOIN imported_fastcup_matches winner_source
  ON winner_source.slug = source.slug AND winner_source."matchKey" = source."winnerToKey"
LEFT JOIN tournament_matches winner_match
  ON winner_match.tournament_id = tournament.id
 AND winner_match.sort_order = winner_source."sortOrder"
LEFT JOIN imported_fastcup_matches loser_source
  ON loser_source.slug = source.slug AND loser_source."matchKey" = source."loserToKey"
LEFT JOIN tournament_matches loser_match
  ON loser_match.tournament_id = tournament.id
 AND loser_match.sort_order = loser_source."sortOrder"
WHERE source_match.tournament_id = tournament.id
  AND source_match.sort_order = source."sortOrder";

CREATE TEMP TABLE imported_fastcup_rules ON COMMIT DROP AS
SELECT * FROM jsonb_to_recordset($rules$
[{"slug":"ls-fastcup-10","sortOrder":1,"ruleText":"Регистрация на турнир проходит через @frokeng в личные сообщения в Discord в формате: название, 5 никнеймов по ролям."},{"slug":"ls-fastcup-10","sortOrder":2,"ruleText":"Регистрировать на турнир в составах команд можно только игроков, заигранных ранее в ивентах летнего DPC-межсезонья Linken's Sphere. Исключение - один слот в команде может занять \"легионер\" (см п.12). В последний день регистрации (8 августа) разрешено взять двух \"легионеров\" в команду."},{"slug":"ls-fastcup-10","sortOrder":3,"ruleText":"При регистрации команды сумма тиров всех 5 игроков из Тир игроков должна составлять не более 35. Игроков 10 тира может быть не более одного на команду."},{"slug":"ls-fastcup-10","sortOrder":4,"ruleText":"Команде разрешено сделать замену, но не более одной замены. Воспользоваться заменой можно на одной карте за турнир. Замену нужно согласовать с организатором."},{"slug":"ls-fastcup-10","sortOrder":5,"ruleText":"На турнире предусмотрено 4 слота для команд. Если команд будет больше предусмотренного, турнир будет проведен на 6 команды. Формат может быть изменен."},{"slug":"ls-fastcup-10","sortOrder":6,"ruleText":"Матч проводится на сервере Стокгольм с турнирым билетом, доступен для зрителей с задержкой 5 минут."},{"slug":"ls-fastcup-10","sortOrder":7,"ruleText":"Правила выбора стороны и очередности пика аналогичны другим серверным турнирам. В бо1 матчах монетка, в бо2 матчах на первой карте монетка, на второй сторону или очередность пика выбирает команда, проигравшая бросок монетки на первой карте, в бо3 аналогично бо2, но на третьей карте монетка."},{"slug":"ls-fastcup-10","sortOrder":8,"ruleText":"Дата и время старта матчей указаны на листе \"турнир\". Опоздание команды более чем на 30 минут на игру приведет к её дисквалификации. Опоздание до 10 минут без штрафа. Опоздание от 10 до 20 минут - выбор аспекта для последнего выбранного героя нарушителей оппонентом на первой карте серии. Опоздание от 20 до 30 минут - выбор стороны и очереди пика достается оппоненту на всю серию, выбор аспекта для последнего выбранного героя нарушителей оппонентом на первой карте. Опоздание более чем на 30 минут - техническое поражение на первой карте и выбор стороны и очереди пика достается оппоненту на всю серию, выбор аспекта для последнего выбранного героя нарушителей оппонентом на каждой из карт. Присутствие команды - это 5 игроков в слотах игрового лобби и войс-канале одновременно."},{"slug":"ls-fastcup-10","sortOrder":9,"ruleText":"Пауза на карту - не более 15 минут на команду в бо1 матчах и не более 25 на команду в серии в бо3 матчах."},{"slug":"ls-fastcup-10","sortOrder":10,"ruleText":"Для участия в матче игроки устанавливают в Steam и в \"изменить проф. информацию и команды\" в настройках в клиенте игры свой серверный ник, если его нет - нужно пройти регистрацию на сервере."},{"slug":"ls-fastcup-10","sortOrder":11,"ruleText":"Каждая команда обязана создать себе команду в клиенте игры."},{"slug":"ls-fastcup-10","sortOrder":12,"ruleText":"Одобренные зарегистрированные команды появятся в разделе Составы."},{"slug":"ls-fastcup-10","sortOrder":13,"ruleText":"Легионерами считаются игроки не участвовавшие в ивентах в ходе DPC-межсезонья и сыгравшие менее 60 игр в рейтинговом режиме за последние 3 месяца."},{"slug":"ls-fastcup-10","sortOrder":14,"ruleText":"Правила могут дополняться как до, так и в ходе турнира."},{"slug":"ls-fastcup-11","sortOrder":1,"ruleText":"Регистрация на турнир проходит через @frokeng в личные сообщения в Discord в формате: название, 5 никнеймов по ролям."},{"slug":"ls-fastcup-11","sortOrder":2,"ruleText":"Регистрировать на турнир в составах команд можно только игроков, заигранных ранее в ивентах летнего DPC-межсезонья Linken's Sphere. Исключение - один слот в команде может занять \"легионер\" (см п.12). В последние 2 дня регистрации (26-27 сентября августа) разрешено взять двух \"легионеров\" в команду."},{"slug":"ls-fastcup-11","sortOrder":3,"ruleText":"При регистрации команды сумма тиров всех 5 игроков из Тир игроков должна составлять не более 37. Игроков 11/10 тира может быть не более одного на команду. Если в команде есть игрок 11/10-го тира, в команде не может быть более 1 игрока 9-го тира. В команде не может быть более 3 игроков 8 и выше тиров. При наличии игроков 11/10 и 9 тира в одной команде - она более не может иметь игроков 8 тира или выше. 11-й тир - особый тир в формате эксперимента для текущего фасткапа."},{"slug":"ls-fastcup-11","sortOrder":4,"ruleText":"Для регистрации на турнире каждый участник команды должен иметь любую Boosty-подписку на Linken's Sphere. Если в команде есть игрок с уникальной ролью (уровень поддержки 1 или 2) - один другой игрок в команде может играть без подписки, но не более одного использования на команду, даже если игроков с уровнем поддержки 1/2 два или более."},{"slug":"ls-fastcup-11","sortOrder":5,"ruleText":"Команде разрешено сделать замену, но не более одной замены. Воспользоваться заменой можно на одной карте за турнир. Замену нужно согласовать с организатором."},{"slug":"ls-fastcup-11","sortOrder":6,"ruleText":"На турнире предусмотрено 4 слота для команд. Если команд будет больше предусмотренного, турнир будет проведен на 6 команды. Формат может быть изменен."},{"slug":"ls-fastcup-11","sortOrder":7,"ruleText":"Матч проводится на сервере Стокгольм без турнирного билета, доступен для зрителей с задержкой 2 минуты при просмотре через друзей в матче."},{"slug":"ls-fastcup-11","sortOrder":8,"ruleText":"Правила выбора стороны и очередности пика аналогичны другим серверным турнирам. В бо1 матчах монетка, в бо2 матчах на первой карте монетка, на второй сторону или очередность пика выбирает команда, проигравшая бросок монетки на первой карте, в бо3 аналогично бо2, но на третьей карте монетка."},{"slug":"ls-fastcup-11","sortOrder":9,"ruleText":"Дата и время старта матчей указаны на листе \"турнир\". Опоздание команды более чем на 30 минут на игру приведет к её дисквалификации. Опоздание до 10 минут без штрафа. Опоздание от 10 до 20 минут - выбор аспекта для последнего выбранного героя нарушителей оппонентом на первой карте серии. Опоздание от 20 до 30 минут - выбор стороны и очереди пика достается оппоненту на всю серию, выбор аспекта для последнего выбранного героя нарушителей оппонентом на первой карте. Опоздание более чем на 30 минут - техническое поражение на первой карте и выбор стороны и очереди пика достается оппоненту на всю серию, выбор аспекта для последнего выбранного героя нарушителей оппонентом на каждой из карт. Присутствие команды - это 5 игроков в слотах игрового лобби и войс-канале одновременно."},{"slug":"ls-fastcup-11","sortOrder":10,"ruleText":"Пауза на карту - не более 15 минут на команду в бо1 матчах и не более 25 на команду в серии в бо3 матчах."},{"slug":"ls-fastcup-11","sortOrder":11,"ruleText":"Тайбрейк на 3 команды играется на кастомной карте Overthrow 3.0 (5x3), при равеном результате 2-х команд в группе выше ставится победившая в личной встрече (или переигровка бо1 турбо или CM, если личной встречи не было)."},{"slug":"ls-fastcup-11","sortOrder":12,"ruleText":"Для участия в матче игроки устанавливают в Steam и в \"изменить проф. информацию и команды\" в настройках в клиенте игры свой серверный ник, если его нет - нужно пройти регистрацию на сервере."},{"slug":"ls-fastcup-11","sortOrder":13,"ruleText":"Каждая команда обязана создать себе команду в клиенте игры."},{"slug":"ls-fastcup-11","sortOrder":14,"ruleText":"Одобренные зарегистрированные команды появятся в разделе Составы."},{"slug":"ls-fastcup-11","sortOrder":15,"ruleText":"Легионерами считаются игроки не участвовавшие в 1 и 2 турах лиги 7-го сезона и сыгравшие менее 70 игр в рейтинговом режиме за последние 3 месяца."},{"slug":"ls-fastcup-11","sortOrder":16,"ruleText":"Правила могут дополняться как до, так и в ходе турнира."},{"slug":"ls-fastcup-12","sortOrder":1,"ruleText":"Регистрация на турнир проходит через @frokeng в личные сообщения в Discord в формате: название, 5 никнеймов по ролям."},{"slug":"ls-fastcup-12","sortOrder":2,"ruleText":"К регистрации допущены заигранные на сервере игроки, разъяснение статуса \"легионера\", как незаигранного игрока, находится в пункте 14 действующих правил. Исключение - один слот в команде может занять \"легионер\" (см п.14). В последние два дня регистрации (20-21 марта) разрешено взять двух \"легионеров\" в команду."},{"slug":"ls-fastcup-12","sortOrder":3,"ruleText":"При регистрации команды сумма тиров всех 5 игроков из Тир игроков должна составлять не более 37. Игроков 10/11 тира может быть не более одного на команду."},{"slug":"ls-fastcup-12","sortOrder":4,"ruleText":"Команде разрешено сделать замену, но не более одной замены. Воспользоваться заменой можно на одной карте за турнир. Замену нужно согласовать с организатором. Возможны исключения на усмотрение организатора."},{"slug":"ls-fastcup-12","sortOrder":5,"ruleText":"На турнире предусмотрено 4 слота для команд. Если команд будет больше предусмотренного, турнир будет проведен на 6 команды. Формат может быть изменен."},{"slug":"ls-fastcup-12","sortOrder":6,"ruleText":"Матч проводится на сервере Стокгольм, без турнирного билета."},{"slug":"ls-fastcup-12","sortOrder":7,"ruleText":"Правила выбора стороны и очередности пика аналогичны другим серверным турнирам. В бо1 матчах монетка, в бо2 матчах на первой карте монетка, на второй сторону или очередность пика выбирает команда, проигравшая бросок монетки на первой карте, в бо3 аналогично бо2, но на третьей карте монетка."},{"slug":"ls-fastcup-12","sortOrder":8,"ruleText":"Дата и время старта матчей указаны на листе \"турнир\". Опоздание команды более чем на 30 минут на игру приведет к её дисквалификации. Опоздание до 10 минут без штрафа. Опоздание от 10 до 20 минут - выбор стороны и очереди пика достается оппоненту на всю серию, штраф времени пика 2-го уровня. Опоздание от 20 до 30 минут - выбор стороны и очереди пика достается оппоненту на всю серию, штраф времени пика 2-го уровня, выбор аспекта для последнего выбранного героя нарушителей оппонентом на первой карте. Опоздание более чем на 30 минут - техническое поражение на первой карте и выбор стороны и очереди пика достается оппоненту на всю серию, выбор аспекта для последнего выбранного героя нарушителей оппонентом на каждой из карт. Присутствие команды - это 5 игроков в слотах игрового лобби и войс-канале одновременно."},{"slug":"ls-fastcup-12","sortOrder":9,"ruleText":"В случае назначения переигровок, игровые дни могут быть продлены, в случае тай-брейка между двумя командами, выше в таблице считается команда, которая победила в личной встрече между этими двумя командами. При тай-брейке на 3 команды играется Overthrow 3.0 (без раннего драфта для премиум-участников, но без запрета на рероллы) 5х3 или 3 круговых бо1 в тот же или в следующий день до старта полуфинала (старт не позже 16:00 второго дня), если на это согласны все команды."},{"slug":"ls-fastcup-12","sortOrder":10,"ruleText":"Пауза на карту - не более 15 минут на команду в бо1 матчах и не более 25 на команду в серии в бо3 матчах."},{"slug":"ls-fastcup-12","sortOrder":11,"ruleText":"Для участия в матче игроки устанавливают в Steam и в \"изменить проф. информацию и команды\" в настройках в клиенте игры свой серверный ник, если его нет - нужно пройти регистрацию на сервере."},{"slug":"ls-fastcup-12","sortOrder":12,"ruleText":"Каждая команда обязана создать себе команду в клиенте игры."},{"slug":"ls-fastcup-12","sortOrder":13,"ruleText":"Одобренные зарегистрированные команды появятся в разделе Составы."},{"slug":"ls-fastcup-12","sortOrder":14,"ruleText":"Легионерами считаются игроки не участвовавшие в первых 6 турах лиги 8-го сезона и/или сыгравшие менее 60 игр в рейтинговом режиме за последние 3 месяца."},{"slug":"ls-fastcup-12","sortOrder":15,"ruleText":"Правила могут дополняться как до, так и в ходе турнира."},{"slug":"ls-fastcup-13","sortOrder":1,"ruleText":"Регистрация на турнир проходит через @frokeng в личные сообщения в Discord в формате: название, 5 никнеймов по ролям."},{"slug":"ls-fastcup-13","sortOrder":2,"ruleText":"К регистрации допущены заигранные на сервере игроки, разъяснение статуса \"легионера\", как незаигранного игрока, находится в пункте 15 действующих правил. Исключение - один слота в команде может занять \"легионер\" (см п.15). В последние два дня регистрации (12-13 июня) разрешено взять двух \"легионеров\" в команду."},{"slug":"ls-fastcup-13","sortOrder":3,"ruleText":"При регистрации команды сумма тиров всех 5 игроков из Тир игроков должна составлять не более 40. В команде должен быть минимум 1 игрок 4-6 тира."},{"slug":"ls-fastcup-13","sortOrder":4,"ruleText":"Команде разрешено сделать замену, но не более одной замены. Воспользоваться заменой можно на одной карте за турнир. Замену нужно согласовать с организатором. Возможны исключения на усмотрение организатора."},{"slug":"ls-fastcup-13","sortOrder":5,"ruleText":"На турнире предусмотрено 4 слота для команд. Если команд будет больше предусмотренного, турнир будет проведен на 6 команды. Формат может быть изменен."},{"slug":"ls-fastcup-13","sortOrder":6,"ruleText":"Матч проводится на сервере Стокгольм, без турнирного билета."},{"slug":"ls-fastcup-13","sortOrder":7,"ruleText":"Для участия в турнире все участники команды должны иметь любую Boosty-подписку."},{"slug":"ls-fastcup-13","sortOrder":8,"ruleText":"Правила выбора стороны и очередности пика аналогичны другим серверным турнирам. В бо1 матчах монетка, в бо2 матчах на первой карте монетка, на второй сторону или очередность пика выбирает команда, проигравшая бросок монетки на первой карте, в бо3 аналогично бо2, но на третьей карте монетка."},{"slug":"ls-fastcup-13","sortOrder":9,"ruleText":"Дата и время старта матчей указаны на листе \"турнир\". Опоздание команды более чем на 30 минут на игру приведет к её дисквалификации. Опоздание до 10 минут без штрафа. Опоздание от 10 до 20 минут - выбор стороны и очереди пика достается оппоненту на всю серию, штраф времени пика 2-го уровня. Опоздание от 20 до 30 минут - выбор стороны и очереди пика достается оппоненту на всю серию, штраф времени пика 2-го уровня, выбор аспекта для последнего выбранного героя нарушителей оппонентом на первой карте. Опоздание более чем на 30 минут - техническое поражение на первой карте и выбор стороны и очереди пика достается оппоненту на всю серию, выбор аспекта для последнего выбранного героя нарушителей оппонентом на каждой из карт. Присутствие команды - это 5 игроков в слотах игрового лобби и войс-канале одновременно."},{"slug":"ls-fastcup-13","sortOrder":10,"ruleText":"В случае назначения переигровок, игровые дни могут быть продлены, в случае тай-брейка между двумя командами, выше в таблице считается команда, которая победила в личной встрече между этими двумя командами. При тай-брейке на 3 команды играется Overthrow 3.0 (без раннего драфта для премиум-участников, но без запрета на рероллы) 5х3 или 3 круговых бо1 в тот же или в следующий день до старта полуфинала (старт не позже 16:00 второго дня), если на это согласны все команды."},{"slug":"ls-fastcup-13","sortOrder":11,"ruleText":"Пауза на карту - не более 15 минут на команду в бо1 матчах и не более 25 на команду в серии в бо3 матчах."},{"slug":"ls-fastcup-13","sortOrder":12,"ruleText":"Для участия в матче игроки устанавливают в Steam и в \"изменить проф. информацию и команды\" в настройках в клиенте игры свой серверный ник, если его нет - нужно пройти регистрацию на сервере."},{"slug":"ls-fastcup-13","sortOrder":13,"ruleText":"Каждая команда обязана создать себе команду в клиенте игры."},{"slug":"ls-fastcup-13","sortOrder":14,"ruleText":"Одобренные зарегистрированные команды появятся в разделе Составы."},{"slug":"ls-fastcup-13","sortOrder":15,"ruleText":"Легионерами считаются игроки не участвовавшие в ивентах 8-го тура лиги и 1-м туре лиги межсезонья."},{"slug":"ls-fastcup-13","sortOrder":16,"ruleText":"Правила могут дополняться как до, так и в ходе турнира."}]
$rules$::jsonb) AS source(
  slug TEXT, "sortOrder" SMALLINT, "ruleText" TEXT
);

INSERT INTO tournament_rules (tournament_id, sort_order, rule_text)
SELECT tournament.id, source."sortOrder", source."ruleText"
FROM imported_fastcup_rules source
JOIN tournaments tournament ON tournament.slug = source.slug
ON CONFLICT (tournament_id, sort_order) DO NOTHING;

INSERT INTO tournament_team_results (application_id, placement, result_label)
SELECT application.id, source.placement, source."resultLabel"
FROM imported_fastcup_teams source
JOIN tournaments tournament ON tournament.slug = source.slug
JOIN tournament_team_applications application
  ON application.tournament_id = tournament.id
 AND application.team_name = source."teamName"
ON CONFLICT (application_id) DO NOTHING;

INSERT INTO tournament_prizes (
  tournament_id, placement, application_id, team_name_snapshot, prize_text
)
SELECT tournament.id, source.placement, application.id,
  source."teamName", source."prizeText"
FROM imported_fastcup_teams source
JOIN tournaments tournament ON tournament.slug = source.slug
JOIN tournament_team_applications application
  ON application.tournament_id = tournament.id
 AND application.team_name = source."teamName"
WHERE source.placement IS NOT NULL
ON CONFLICT (tournament_id, placement) DO NOTHING;

CREATE TEMP TABLE imported_fastcup_schedule ON COMMIT DROP AS
SELECT * FROM jsonb_to_recordset($schedule$
